definition.script:
node {
    stage('Use folder-scoped Conjur credential') {
        withCredentials([
            conjurSecretCredential(credentialsId: '{{DISCO-CONJUR-PIPELINE-CREDENTIAL-ID}}', variable: 'DISCO_CONJUR_SECRET')
        ]) {
            sh '''#!/bin/bash
            set -euo pipefail
            test -n "$DISCO_CONJUR_SECRET"
            echo "DisCo Conjur folder credential binding succeeded"
            '''
        }
    }
}
